const out = [];
function pickDescription(j) {
  const rss =
    j.DescriptionRaw ||        // added
    j.contentSnippet ||
    j.content ||
    j.summary ||
    j.description ||
    j["content:encoded"] ||
    "";
  const eb =
    j.summary ||
    (j.description && (j.description.text || j.description.html)) ||
    j.structured_content ||
    "";
  const d = (eb || rss || "").toString().trim();
  return d;
}
for (const item of items) {
  const j = item.json || {};
  const title = (j.title || j.name || "").toString().trim();
  const link = (j.link || j.url || "").toString().trim();
  // Facebook manual-intake events arrive linkless (feed screenshots carry no URLs);
  // let them through if they have a title. All other sources still require a link.
  // Editor adds the link at selection; a pre-publish guard blocks featuring linkless.
  if (!title || (!link && j.sourceCanonical !== 'Facebook')) continue;

  // #112 / R7 Stage 0 - Eventbrite serves global events into city queries (#59/#81).
  // ALLOWLIST, not a blocklist, deliberately: the old ".de/.fr/.co.uk/.sg" list caught
  // 29 foreign rows and MISSED 9 on .nl/.be/.com.au/.at/.ch (n=624, measured 2026-07-28).
  // eventbrite.com MUST stay: 20.6% includable (7 of 34) - dropping it kills 7 keepers.
  // forms.gle deliberately NOT blocked: a Google Form is a registration mechanism small
  // local organizers use, not a geography signal.
  if (link) {
    const hostMatch = link.match(/^https?:\/\/(?:www\.)?([^\/]+)/i);
    const host = hostMatch ? hostMatch[1].toLowerCase() : '';
    if (/(^|\.)eventbrite\./.test(host) && !/(^|\.)eventbrite\.(ca|com)$/.test(host)) continue;
  }

  const isoDate = (j.isoDate || j.start_date || j.startDate || "").toString().trim();
  const guid = (j.guid || j.eventbrite_event_id || j.id || "").toString().trim();
  const DescriptionRaw = pickDescription(j);
  out.push({
    json: {
      title,
      link,
      pubDate: (j.pubDate || "").toString(),
      isoDate,
      guid,
      DescriptionRaw,
      endDate: (j.endDate || ''),  // added
      locationName: (j.locationName || "").toString(),
      sourceCanonical: (j.sourceCanonical || "").toString(),
      city: (j.city || ''),
      // Discrete source-metadata fields (currently AllEvents only). This node rebuilds
      // json from an allowlist, so these MUST be carried here or they're dropped before
      // Build Upsert. Defaults keep them harmless for sources that don't set them.
      organizer: (j.organizer || ''),
      sourceScore: (j.sourceScore != null ? j.sourceScore : null),
      categories: (j.categories || ''),
      costRaw: (j.costRaw || ''),
      _valid: true,
    },
  });
}
return out;

// Sort items newest → oldest based on isoDate or pubDate
function toTs(x) {
  if (!x) return 0;
  const d = new Date(x);
  return isNaN(d.getTime()) ? 0 : d.getTime();
}

const arr = items.map(i => i);
arr.sort((a, b) => {
  const A = toTs(a.json.isoDate || a.json.pubDate);
  const B = toTs(b.json.isoDate || b.json.pubDate);
  return B - A;
});

return arr;

// NORMALIZATION_VERSION: v2 (2026-06-07)
// Keep byte-identical with scripts/updateUniqueEventIDs.js norm().
// If you change one, change both, then re-run the backfill script.
function decodeEntities(s) {
  return s
    .replace(/&#(\d+);/g, (_, n) => String.fromCodePoint(parseInt(n, 10)))
    .replace(/&#x([0-9a-f]+);/gi, (_, n) => String.fromCodePoint(parseInt(n, 16)))
    .replace(/&amp;/g, '&')
    .replace(/&apos;/g, "'")
    .replace(/&quot;/g, '"')
    .replace(/&lt;/g, '<')
    .replace(/&gt;/g, '>');
}
function straighten(s) {
  return s
    .replace(/[‘’‚‛]/g, "'")
    .replace(/[“”„‟]/g, '"')
    .replace(/[–—−]/g, '-')
    .replace(/[  -   　]/g, ' ')
    .replace(/…/g, '...');
}
function norm(s) {
  return straighten(decodeEntities((s || '').toString()))
    .normalize('NFC')
    .trim()
    .toLowerCase()
    .replace(/\s+/g, ' ');
}
function dateOnly(d) {
  const dt = new Date(d);
  if (isNaN(dt.getTime())) return '';
  return dt.toISOString().slice(0, 10);
}
const rawTitle = $json.title || $json.event_name || '';
const titleNorm = norm(rawTitle);
const link = $json.link || $json.url || $json.linkUrl || $json.link_url || '';
const day = dateOnly($json.isoDate || $json.pubDate);
const hasUrl = !!link;
const hasDate = !!day;
return {
  ...$json,
  event_name: rawTitle,
  url: link,
  start_date: day,
  uniqueEventID: `${titleNorm}|${day}`,
  city: $json.city || 'Vaughan',
  _valid: hasUrl && hasDate,
  _invalid_reason: !hasUrl ? 'missing_url' : (!hasDate ? 'missing_date' : ''),
};

const DAYS_AHEAD = 30;

const today = new Date();
const startOfToday = new Date(today.getFullYear(), today.getMonth(), today.getDate());
const endDate = new Date(startOfToday);
endDate.setDate(endDate.getDate() + DAYS_AHEAD);

const startRaw = $json.start_date || $json.isoDate || '';

if (!startRaw) {
  return null; // drop if no date
}

const eventDate = new Date(startRaw);
if (isNaN(eventDate.getTime())) {
  return null; // drop invalid date
}

const eventDateOnly = new Date(eventDate.getFullYear(), eventDate.getMonth(), eventDate.getDate());

if (eventDateOnly < startOfToday) {
  return null; // drop past events
}

if (eventDateOnly > endDate) {
  return null; // drop too far in future
}

return $json;

const response = $input.first().json;

const allEvents = [];

// Geo allowlist (#59): Eventbrite's city-browse leaks neighbouring municipalities
// (Newmarket, Aurora, Schomberg, Gormley, Whitchurch-Stouffville, Georgina, Toronto...)
// into the target-city result set. Gate to the covered municipalities and canonicalize,
// mirroring the AllEvents branch. Unmapped venue city = drop. (R5 / Decision_Log §52)
const CITY_MAP = {
  'Vaughan': 'Vaughan', 'Woodbridge': 'Vaughan', 'Thornhill': 'Vaughan',
  'Maple': 'Vaughan', 'Concord': 'Vaughan', 'Kleinburg': 'Vaughan',
  'Richmond Hill': 'Richmond Hill', 'Markham': 'Markham', 'Unionville': 'Markham',
};

function formatPrice(ta) {
  if (!ta) return '';
  if (ta.is_free) return 'Free';
  const min = ta.minimum_ticket_price, max = ta.maximum_ticket_price;
  if (!min && !max) return '';
  if (min && max && min.display === max.display) return min.display;
  if (min && max) return min.display + ' - ' + max.display;
  return (min || max).display;
}

// Eventbrite Search1 returns events.results (2026-10-15); city-browse returned buckets[].events[].
const events = response.events && response.events.results
  ? response.events.results
  : (response.buckets || []).flatMap((b) => b.events || []);
for (const event of events) {
    const venue = event.primary_venue || {};
    const venueName = (venue.name || '').trim();
    const venueCity = ((venue.address && venue.address.city) || '').trim();
    // Drop venueless events: Eventbrite's city-browse serves global online events to every
    // city query, so a blank venue city has NO geographic anchor (mostly foreign/B2B webinars
    // that were being silently stamped 'Vaughan' by Make UniqueEventID downstream). Unlike the
    // local-library feed, this source gives no locality guarantee for a venueless event.
    // (#81, R5 / Decision_Log §52)
    if (!venueCity) continue;
    // Geo allowlist gate (#59): keep only covered municipalities, canonicalize the rest.
    const city = CITY_MAP[venueCity];
    if (!city) continue;
    // Sold-out gate (#84): a sold-out event has zero reader utility (can't be attended) -
    // hard exclusion, not a data point to carry. Mirrors Chef Upstairs' existing bookedOut
    // filter. (Decision_Log §54 addendum - capture vs filter test.)
    const ta = event.ticket_availability;
    if (ta && ta.is_sold_out === true) continue;
    // Cost signal (#84) - reader-facing, kept as source-formatted text (Decision_Log §54).
    const costRaw = formatPrice(ta);
    // Category reshape (#84): tags[] mixes real taxonomy (EventbriteCategory/EventbriteFormat)
    // with per-organizer marketing noise (OrganizerTag/*) - keep only the taxonomy prefixes.
    const categories = (event.tags || [])
      .filter(t => t.prefix === 'EventbriteCategory' || t.prefix === 'EventbriteFormat')
      .map(t => t.display_name)
      .filter(Boolean)
      .join(', ');
    allEvents.push({
      json: {
        ...event,
        sourceCanonical: 'Eventbrite',
        locationName: venueName,
        city,
        costRaw,
        categories,
      }
    });
}

return allEvents;

const sourceCanonical = 'McMichael';
const locationName = 'McMichael Canadian Art Collection';

// IMPORTANT: the shared 'Make UniqueEventID' node downstream RECOMPUTES
// uniqueEventID from this branch's `title` field using its own plain
// lowercase+whitespace normalization — it overwrites whatever ID we compute
// here. So the only way to land on the SAME id as the existing iCal-derived
// records is to make `title` itself match — i.e. decode HTML entities to
// STRAIGHT ascii quotes (matching the existing dataset convention), not to
// their typographically-correct curly Unicode equivalents. Decoding to curly
// quotes is "more correct" in isolation but produces a `title` that
// Make UniqueEventID then normalizes into a DIFFERENT id than the existing
// record — creating a duplicate. Consistency with the existing convention
// wins over typographic purity here.
function decodeEntities(str) {
  if (!str) return str;
  return str
    .replace(/&#821[678];|&#x201[89][a-fA-F]?;|&lsquo;|&rsquo;/g, "'")
    .replace(/&#822[01];|&#x201[CcDd];|&ldquo;|&rdquo;/g, '"')
    .replace(/&#8211;|&#8212;|&#x201[34];|&ndash;|&mdash;/g, '—')
    .replace(/&#039;|&#39;|&apos;/g, "'")
    .replace(/&#(\d+);/g, (_, code) => String.fromCharCode(parseInt(code, 10)))
    .replace(/&#x([0-9a-fA-F]+);/g, (_, code) => String.fromCharCode(parseInt(code, 16)))
    .replace(/&amp;/g, '&')
    .replace(/&lt;/g, '<')
    .replace(/&gt;/g, '>')
    .replace(/&quot;/g, '"')
    .replace(/&nbsp;/g, ' ');
}

const out = [];
const seen = new Set();

for (const inputItem of $input.all()) {
  const response = inputItem.json;
  const events = response.events || [];

  for (const ev of events) {
    const title = decodeEntities((ev.title || '').toString().trim());
    const link = (ev.url || ev.website || '').toString().trim();
    const startRaw = (ev.start_date || '').toString().trim();
    if (!title || !startRaw) continue;

    const isoDate = startRaw.replace(' ', 'T');
    const dateOnly = startRaw.slice(0, 10);
    const titleNorm = title.toLowerCase().replace(/\s+/g, ' ');
    const uniqueEventID = `${titleNorm}|${dateOnly}`;
    if (seen.has(uniqueEventID)) continue;
    seen.add(uniqueEventID);

    const description = decodeEntities((ev.description || '').toString().trim());
    const categories = (ev.categories || []).map(c => (c && c.name) ? c.name : '').filter(Boolean);
    const DescriptionRaw = categories.length
      ? `Categories: ${categories.join(', ')}\n\n${description}`
      : description;

    out.push({
      json: {
        title,
        link,
        event_name: title,
        url: link,
        isoDate,
        start_date: dateOnly,
        uniqueEventID,
        city: 'Vaughan',
        locationName,
        sourceCanonical,
        DescriptionRaw,
        _valid: !!title && !!dateOnly && !!link,
        _invalid_reason: !title ? 'missing_title' : (!dateOnly ? 'missing_date' : (!link ? 'missing_url' : ''))
      }
    });
  }
}

return out;

const PER_PAGE = 50;
const BASE_URL = 'https://mcmichael.com/wp-json/tribe/events/v1/events';
const totalPages = $input.first().json.total_pages || 1;

const urls = [];
for (let page = 1; page <= totalPages; page++) {
  urls.push({ json: { url: `${BASE_URL}?page=${page}&per_page=${PER_PAGE}` } });
}
return urls;

const xml = $input.first().json.data;

function decodeEntities(s) {
  return s
    .replace(/&#(\d+);/g, (_, n) => String.fromCodePoint(parseInt(n, 10)))
    .replace(/&#x([0-9a-f]+);/gi, (_, n) => String.fromCodePoint(parseInt(n, 16)))
    .replace(/&amp;/g, '&')
    .replace(/&apos;/g, "'")
    .replace(/&quot;/g, '"')
    .replace(/&lt;/g, '<')
    .replace(/&gt;/g, '>')
    .replace(/&nbsp;/g, ' ');
}

const itemBlocks = [];
const itemRegex = /<item>([\s\S]*?)<\/item>/g;
let match;
while ((match = itemRegex.exec(xml)) !== null) {
  itemBlocks.push(match[1]);
}

const get = (block, tag) => {
  const m = block.match(new RegExp(`<${tag}[^>]*>(?:<!\\[CDATA\\[([\\s\\S]*?)\\]\\]>|([\\s\\S]*?))<\\/${tag}>`));
  return m ? (m[1] ?? m[2] ?? '').trim() : '';
};

const getEvent = (block, field) => {
  const m = block.match(new RegExp(`<event_listing:${field}[^>]*>(?:<!\\[CDATA\\[([\\s\\S]*?)\\]\\]>|([\\s\\S]*?))<\/event_listing:${field}>`));
  return m ? (m[1] ?? m[2] ?? '').trim() : '';
};

const results = [];

for (const block of itemBlocks) {
  const location = getEvent(block, 'location');

  const isKortright = location.includes('Pine Valley') || location.includes('Kortright');
  const isBlackCreek = location.includes('Murray Ross');

  if (!isKortright && !isBlackCreek) continue;

  const title = decodeEntities(get(block, 'title'));  // ← decode added
  const description = decodeEntities(get(block, 'description'));
  const link = get(block, 'link');
  const startRaw = getEvent(block, 'start_date');
  const endRaw = getEvent(block, 'end_date');
  // #84 - clean Free/Paid enum, reader-facing cost signal (Decision_Log §54).
  const costRaw = getEvent(block, 'ticket_price');

  const isoDate = startRaw ? new Date(startRaw.replace(' ', 'T')).toISOString() : '';
  const endDate = endRaw ? endRaw.split(' ')[0] : '';

  const locationName = isKortright
    ? 'Kortright Centre for Conservation'
    : 'Black Creek Pioneer Village';

  results.push({
    json: {
      title,
      event_name: title,
      link,
      url: link,
      isoDate,
      start_date: isoDate,
      endDate,
      locationName,
      city: 'Vaughan',
      sourceCanonical: 'TRCA Calendar',
      DescriptionRaw: description,
      costRaw,
      _valid: !!(title && isoDate && link),
    }
  });
}

return results;

const xml = $input.first().json.data;

function decodeEntities(s) {
  return s
    .replace(/&#(\d+);/g, (_, n) => String.fromCodePoint(parseInt(n, 10)))
    .replace(/&#x([0-9a-f]+);/gi, (_, n) => String.fromCodePoint(parseInt(n, 16)))
    .replace(/&amp;/g, '&')
    .replace(/&apos;/g, "'")
    .replace(/&quot;/g, '"')
    .replace(/&lt;/g, '<')
    .replace(/&gt;/g, '>')
    .replace(/&nbsp;/g, ' ');
}

function stripCdata(s) {
  return s.replace(/^<!\[CDATA\[([\s\S]*?)\]\]>$/, '$1').trim();
}

function stripHtml(s) {
  return s.replace(/<[^>]*>/g, ' ').replace(/\s+/g, ' ').trim();
}

const CITY_MAP = {
  'Markham': 'Markham',
  'Unionville': 'Markham',
  'Thornhill': 'Vaughan',
  'Vaughan': 'Vaughan',
  'Richmond Hill': 'Richmond Hill',
};

const itemBlocks = [];
const itemRegex = /<item>([\s\S]*?)<\/item>/g;
let match;
while ((match = itemRegex.exec(xml)) !== null) {
  itemBlocks.push(match[1]);
}

const get = (block, tag) => {
  const m = block.match(new RegExp(`<${tag}[^>]*>(?:<!\\[CDATA\\[([\\s\\S]*?)\\]\\]>|([\\s\\S]*?))<\\/${tag}>`));
  return m ? (m[1] ?? m[2] ?? '').trim() : '';
};

const getBC = (block, field) => {
  const m = block.match(new RegExp(`<bc:${field}[^>]*>(?:<!\\[CDATA\\[([\\s\\S]*?)\\]\\]>|([\\s\\S]*?))<\/bc:${field}>`));
  return m ? (m[1] ?? m[2] ?? '').trim() : '';
};

const getAudience = (block) => {
  const matches = [...block.matchAll(/<category[^>]*domain="Audience"[^>]*>(?:<!\[CDATA\[([\s\S]*?)\]\]>|([\s\S]*?))<\/category>/g)];
  return matches.map(m => (m[1] ?? m[2] ?? '').trim()).filter(Boolean).join(', ');
};

// #84 - Type taxonomy (e.g. "Storytime"), separate from Audience. Feeds shared SourceCategories.
const getTypeCategory = (block) => {
  const matches = [...block.matchAll(/<category[^>]*domain="Type"[^>]*>(?:<!\[CDATA\[([\s\S]*?)\]\]>|([\s\S]*?))<\/category>/g)];
  return matches.map(m => (m[1] ?? m[2] ?? '').trim()).filter(Boolean).join(', ');
};

// #84 - registration_info.is_full: a hard exclusion (sold-out event has zero reader utility),
// same capture-vs-filter call as Eventbrite/Chef Upstairs (Decision_Log §54 addendum).
const isRegistrationFull = (block) => {
  const ri = getBC(block, 'registration_info');
  return /<bc:is_full>true<\/bc:is_full>/.test(ri);
};

// Extract a sub-field from within bc:location XML
const getFromLocation = (locationXml, field) => {
  const m = locationXml.match(new RegExp(`<bc:${field}[^>]*>([^<]*)<\/bc:${field}>`));
  return m ? m[1].trim() : '';
};

const results = [];

for (const block of itemBlocks) {
  const title = decodeEntities(get(block, 'title'));
  const link = get(block, 'link');
  const startRaw = getBC(block, 'start_date');
  const endRaw = getBC(block, 'end_date');
  const locationXml = getBC(block, 'location');
  const descriptionRaw = stripCdata(get(block, 'description'));
  const description = stripHtml(decodeEntities(descriptionRaw));
  const audience = getAudience(block);
  const categories = getTypeCategory(block);

  if (!title || !startRaw) continue;
  if (isRegistrationFull(block)) continue;

  // The feed gives UTC times (2026-10-29T00:00:00Z is 8 PM on Oct 28 in Markham). Take the date
  // in Toronto time; the UTC date moved every event at 8 PM or later to the next day (2026-10-15).
  const localDate = (raw) => new Date(raw).toLocaleDateString('en-CA', { timeZone: 'America/Toronto' });
  const isoDate = `${localDate(startRaw)}T00:00:00`;
  const endDate = endRaw ? localDate(endRaw) : '';

  const rawLocationName = getFromLocation(locationXml, 'name');
  const bcCity = getFromLocation(locationXml, 'city');

  // A BiblioCommons online/virtual program carries an empty <bc:location> (no name, no city).
  // The feed IS the Markham Public Library, so a venueless event here is a known-local virtual
  // program — keep it (#81, R5; client: seniors value online programs like Yoga for Older Adults).
  // A physical event must still map to a covered city, else drop (geo-leakage guard, Decision_Log §52/#59).
  let city, locationName;
  if (!rawLocationName) {
    city = 'Online';
    locationName = 'Online (Markham Public Library)';
  } else {
    city = CITY_MAP[bcCity] || null;
    if (!city) continue;
    locationName = rawLocationName;
  }

  const DescriptionRaw = audience
    ? `Audience: ${audience}\n\n${description}`
    : description;

  results.push({
    json: {
      title,
      event_name: title,
      link,
      url: link,
      isoDate,
      start_date: isoDate,
      endDate,
      locationName,
      city,
      sourceCanonical: 'BiblioCommons Markham',
      DescriptionRaw,
      categories,
      _valid: !!(title && isoDate && link),
    }
  });
}

return results;

const response = $input.first().json;
// A refused request comes back as HTTP 200 {error:1, message:"invalid_request"} with no events, which
// looked like a quiet week from 2026-09-12 to 2026-10-15. Stop the run instead.
if (response.error) throw new Error(`AllEvents list request refused: ${response.message || 'error'}`);
const events = response.data || [];

function decodeEntities(s) {
  if (!s) return '';
  return s
    .replace(/&#(\d+);/g, (_, n) => String.fromCodePoint(parseInt(n, 10)))
    .replace(/&#x([0-9a-f]+);/gi, (_, n) => String.fromCodePoint(parseInt(n, 16)))
    .replace(/&amp;/g, '&')
    .replace(/&apos;/g, "'")
    .replace(/&quot;/g, '"')
    .replace(/&lt;/g, '<')
    .replace(/&gt;/g, '>');
}

const CITY_MAP = {
  'Vaughan': 'Vaughan',
  'Woodbridge': 'Vaughan',
  'Thornhill': 'Vaughan',
  'Maple': 'Vaughan',
  'Concord': 'Vaughan',
  'Richmond Hill': 'Richmond Hill',
  'Markham': 'Markham',
  'Unionville': 'Markham',
};

// #109 - venue.city is ambiguous ACROSS COUNTRIES. AllEvents' "richmond hill" branch
// returns Richmond Hill GEORGIA and Richmond Hill NEW YORK alongside Richmond Hill ON,
// and CITY_MAP passes all three because the city name is genuinely correct. Measured
// 2026-07-27: 51 of 390 live records (13.1%) were US. venue.full_address is the
// discriminator and the API always carries it (blank on 0 of 390).
const FOREIGN_ADDRESS = /(,\s*(GA|NY|TX|FL|IL|VA|NC|SC|OH|PA|MI|WA|MA|NJ|MD|TN|AZ|CO|OR|MN|WI|IN|MO|AL|KY|LA|OK|CT|IA|MS|AR|KS|UT|NV|NM|NE|WV|ID|HI|ME|NH|RI|MT|DE|SD|ND|AK|VT|WY|DC)\b)|(\bUSA\b)|(\bUnited States\b)/;
const DOMESTIC_ADDRESS = /(,\s*ON\b)|(\bOntario\b)|(\bCanada\b)|([A-Z]\d[A-Z]\s?\d[A-Z]\d)/i;

const results = [];

for (const ev of events) {
  const venue = ev.venue || {};
  const venueCity = (venue.city || '').trim();
  const city = CITY_MAP[venueCity];
  if (!city) continue;

  // #109 - reject only on POSITIVE foreign evidence, never on a missing address.
  // A blank address is not a fact, and Stage 0 may act only on facts. The
  // !DOMESTIC_ADDRESS clause exists because ", CA" is both California and Canada.
  const rawAddress = (venue.full_address || '').toString();
  if (FOREIGN_ADDRESS.test(rawAddress) && !DOMESTIC_ADDRESS.test(rawAddress)) continue;

  const title = decodeEntities((ev.eventname || '').toString().trim());
  const eventUrl = (ev.event_url || ev.share_url || '').toString().trim();
  if (!title || !eventUrl) continue;

  const startTs = ev.start_time;
  if (!startTs) continue;
  const isoDate = new Date(startTs * 1000).toISOString();

  const endTs = ev.end_time;
  const endDate = endTs ? new Date(endTs * 1000).toISOString().slice(0, 10) : '';

  const fullAddress = decodeEntities((venue.full_address || '').toString().trim());
  const locationName = fullAddress.split(',')[0].trim();

  // Source metadata kept as DISCRETE fields (not concatenated into DescriptionRaw).
  // AllEvents' API has no event-description field, so DescriptionRaw is left empty:
  // (a) the old "AllEvents Categories/Organizer/Score" blob made richest-wins
  //     survivorship pick AllEvents over a real-description source on raw length;
  // (b) it polluted the R6 content-scoring signal. See Decision_Log section 51 + #70.
  const baseCategories = Array.isArray(ev.categories)
    ? ev.categories.filter(Boolean).join(', ')
    : (ev.categories || '').toString();
  // #84 - merge tags[]/formats[] (secondary taxonomy, e.g. "festival") into the shared
  // SourceCategories field. Additive to the existing categories[], not a replacement.
  const extraTags = [
    ...(Array.isArray(ev.tags) ? ev.tags : []),
    ...(Array.isArray(ev.formats) ? ev.formats : []),
  ].filter(Boolean);
  const categories = [baseCategories, ...extraTags].filter(Boolean).join(', ');
  const organizer = decodeEntities(((ev.organizer && ev.organizer.name) || ev.organizer || '').toString().trim());
  const sourceScore = ev.score != null ? ev.score : null;
  // #84 - AllEvents pre-formats its own price string (e.g. "CAD 30 to 49", "Free");
