const CITY_MAP = {
  'Vaughan': 'Vaughan',
  'Woodbridge': 'Vaughan',
  'Thornhill': 'Vaughan',
  'Maple': 'Vaughan',
  'Concord': 'Vaughan',
  'Richmond Hill': 'Richmond Hill',
  'Markham': 'Markham',
  'Unionville': 'Markham',
};

// #109 - venue.city is ambiguous ACROSS COUNTRIES. AllEvents' "richmond hill" branch
// returns Richmond Hill GEORGIA and Richmond Hill NEW YORK alongside Richmond Hill ON,
// and CITY_MAP passes all three because the city name is genuinely correct. Measured
// 2026-07-27: 51 of 390 live records (13.1%) were US. venue.full_address is the
// discriminator and the API always carries it (blank on 0 of 390).
