const DOMESTIC_ADDRESS = /(,\s*ON\b)|(\bOntario\b)|(\bCanada\b)|([A-Z]\d[A-Z]\s?\d[A-Z]\d)/i;

const results = [];

for (const ev of events) {
  const venue = ev.venue || {};
  const venueCity = (venue.city || '').trim();
  const city = CITY_MAP[venueCity];
  if (!city) continue;

  // #109 - reject only on POSITIVE foreign evidence, never on a missing address.
