  // SourceCategories field. Additive to the existing categories[], not a replacement.
  const extraTags = [
    ...(Array.isArray(ev.tags) ? ev.tags : []),
    ...(Array.isArray(ev.formats) ? ev.formats : []),
  ].filter(Boolean);
  const categories = [baseCategories, ...extraTags].filter(Boolean).join(', ');
  const organizer = decodeEntities(((ev.organizer && ev.organizer.name) || ev.organizer || '').toString().trim());
  const sourceScore = ev.score != null ? ev.score : null;
  // #84 - AllEvents pre-formats its own price string (e.g. "CAD 30 to 49", "Free");
  // richer/more populated than the sparse tickets{} object (2/225 in sample vs 141/225).
  const costRaw = (ev.display_price_label || '').toString().trim();

  results.push({
    json: {
      title,
      event_name: title,
      link: eventUrl,
      url: eventUrl,
      isoDate,
      start_date: isoDate,
      endDate,
      locationName,
      city,
      sourceCanonical: 'AllEvents',
      DescriptionRaw: '',
      organizer,
      sourceScore,
      categories,
      costRaw,
      _valid: !!(title && isoDate && eventUrl),
    }
  });
}

return results;

