// Group DateWindow output into Airtable batch-upsert bodies (10 records/request).
// Mirrors the old 'Upsert Candidates' field mapping exactly; matches on UniqueEventID.
// Empty values are omitted (avoids 400 on empty date fields; never blanks an existing value).
const FIELD_MAP = {
  'Event Title': 'event_name',
  'City': 'city',
  'URL': 'url',
  'Start Date': 'start_date',
  'End Date': 'endDate',
  'DescriptionRaw': 'DescriptionRaw',
  'UniqueEventID': 'uniqueEventID',
  'LocationName': 'locationName',
  'Source': 'sourceCanonical',
  'Organizer': 'organizer',
  'SourceScore': 'sourceScore',
  'SourceCategories': 'categories',
  'CostRaw': 'costRaw',
};
const now = new Date().toISOString();
function buildFields(j) {
  const f = {};
  for (const [col, key] of Object.entries(FIELD_MAP)) {
    const v = j[key];
    if (v !== undefined && v !== null && v !== '') f[col] = v;
  }
  f['Last Auto Update'] = now;
  return f;
}
// Group by UniqueEventID across the whole run. Airtable rejects a batch that updates
// the same record twice in one request, and re-upserting the same event is pointless.
const groups = new Map(); // id -> [all jsons with this id]
for (const i of items) {
  const id = i.json.uniqueEventID;
  if (!id) continue;
  if (!groups.has(id)) groups.set(id, []);
  groups.get(id).push(i.json);
}
// --- Survivorship: richest-wins golden record (Decision_Log section 51, #70) ---
// Source-agnostic ordered comparator; replaces the old last-in-Merge-order wins.
//   1. URL present beats URL absent  (demotes linkless records; keeps the featured-link path)
//   2. tie -> longer DescriptionRaw  (serves the R6 content scorer; fires only between
//                                     aggregators that both carry a URL, never for Facebook,
//                                     whose intake schema has no description column)
//   3. tie -> last in Merge order    (harmless fallback; preserves prior behaviour)
// Never references sourceCanonical (portability rule). Lock=true rows are untouched:
// Lock lives on IssueItems, not Candidates; editorial Candidate fields (Status, etc.)
// are protected by being absent from FIELD_MAP (Decision_Log section 40).
function richer(a, b) {
  const au = (a.url || '').trim() ? 1 : 0;
  const bu = (b.url || '').trim() ? 1 : 0;
  if (au !== bu) return au > bu ? a : b;
  const ad = (a.DescriptionRaw || '').length;
  const bd = (b.DescriptionRaw || '').length;
  if (ad !== bd) return ad > bd ? a : b;
  return b;
}
// Why did `win` beat `loser`? Replays the same comparator tiers for the run log,
// so maintenance can see the decision per collision (the loser is dropped here and
// never reaches Airtable, so this is the ONLY place the reason can be observed).
function winReason(win, loser) {
  const wu = (win.url || '').trim() ? 1 : 0;
  const lu = (loser.url || '').trim() ? 1 : 0;
  if (wu !== lu) return 'URL';
  if ((win.DescriptionRaw || '').length !== (loser.DescriptionRaw || '').length) return 'longer description';
  return 'merge-order (tie)';
}
// Field-level merge for SUPPLEMENTARY metadata (#70 follow-up, extended #84). Record-level
// richest-wins picks the base record (real description / primary URL); but discrete source
// metadata (organizer / sourceScore / categories / costRaw) is only ever set by a source that
// may LOSE the collision. So overlay those fields from any colliding record that has them, onto
// the winner. Source-agnostic (by field presence, not source name) and only fills BLANKS on the
// winner — it never overwrites a value the winner already carries.
const META_FIELDS = ['organizer', 'sourceScore', 'categories', 'costRaw'];
const isEmpty = (v) => v === undefined || v === null || v === '';
const seen = new Map(); // id -> surviving json (metadata-enriched)
for (const [id, arr] of groups) {
  const win = arr.reduce((w, c) => richer(w, c));
  for (const fld of META_FIELDS) {
    if (isEmpty(win[fld])) {
      const donor = arr.find((r) => !isEmpty(r[fld]));
      if (donor) win[fld] = donor[fld];
    }
  }
  seen.set(id, win);
}
