// Same UniqueEventID + SAME url  = genuinely the same event (benign collapse).
// Same UniqueEventID + DIFFERENT urls = two different events merged on a coarse
// title|date key (potential wrongful loss — inspect these).
const collisions = [...groups.entries()].filter(([, arr]) => arr.length > 1);
const collapsed = items.length - seen.size;
console.log(`[dedup] ${items.length} items in -> ${seen.size} unique (${collapsed} collapsed across ${collisions.length} keys)`);
let urlDiffers = 0;
for (const [id, arr] of collisions) {
  const urls = new Set(arr.map((r) => r.url));
  const venues = new Set(arr.map((r) => (r.locationName || '').trim()).filter(Boolean));
  const bad = urls.size > 1;
  if (bad) urlDiffers++;
  const win = seen.get(id);
  console.log(`  x${arr.length} urls=${urls.size} venues=${venues.size} "${id}"${bad ? ' [URLS DIFFER - INSPECT]' : ''}`);
  for (const r of arr) {
    if (r === win) continue;
    console.log(`      won: ${win.sourceCanonical || '(none)'} over ${r.sourceCanonical || '(none)'} (${winReason(win, r)})`);
  }
}
console.log(`[dedup] ${urlDiffers} collision key(s) had DIFFERING urls (potential wrongful merge; 0 = all collapses benign)`);
// --- DoD safety gate (#70): per-source count diff, before vs after survivorship. ---
// Read with the documented asymmetry: a DROP for Facebook is expected/correct (its
// collisions reattribute to richer aggregators); an aggregator losing records, or FB
// collapsing to ~0, is the red flag.
const tally = (arr) => arr.reduce((m, j) => { const s = j.sourceCanonical || '(none)'; m[s] = (m[s] || 0) + 1; return m; }, {});
const before = tally(items.map((i) => i.json));
const after = tally([...seen.values()]);
const allSources = [...new Set([...Object.keys(before), ...Object.keys(after)])].sort();
console.log('[dedup] per-source before -> after (survivorship):');
for (const s of allSources) console.log(`  ${s}: ${before[s] || 0} -> ${after[s] || 0}`);

const records = [...seen.values()].map((j) => ({ fields: buildFields(j) }));
const out = [];
for (let k = 0; k < records.length; k += 10) {
  out.push({
    json: {
      records: records.slice(k, k + 10),
      performUpsert: { fieldsToMergeOn: ['UniqueEventID'] },
