}
const CITY_MAP = {
  'Vaughan': 'Vaughan', 'Woodbridge': 'Vaughan', 'Thornhill': 'Vaughan',
  'Maple': 'Vaughan', 'Concord': 'Vaughan', 'Kleinburg': 'Vaughan',
  'Richmond Hill': 'Richmond Hill', 'Markham': 'Markham', 'Unionville': 'Markham',
};
const seen = new Set();
const results = [];
for (const item of $input.all()) {
  const byDate = (item.json && item.json.results) || {};
  for (const dateKey of Object.keys(byDate)) {
    const list = (byDate[dateKey] && byDate[dateKey].list_items) || [];
    for (const ev of list) {
      const pid = ev.product_id;
      if (pid != null) {
        if (seen.has(pid)) continue;
        seen.add(pid);
      }
      const title = clean(ev.product_name);
      const link = (ev.product_link || '').toString().trim();
      const startRaw = (ev.product_startdate || '').toString().trim();
      if (!title || !link || !startRaw) continue;
      const isoDate = startRaw.replace(' ', 'T');
      const endRaw = (ev.product_enddate || '').toString().trim();
      const endDate = endRaw ? endRaw.slice(0, 10) : '';
      const rawCity = (ev.product_city || '').toString().trim();
      const city = CITY_MAP[rawCity] || rawCity;
      const venue = clean(ev.product_venue_name) || (ev.product_location_condensed || '').toString().trim();
      const descParts = [];
      if (ev.product_types) descParts.push('Visit Vaughan Types: ' + ev.product_types);
      if (ev.product_cost) descParts.push('Visit Vaughan Cost: ' + clean(ev.product_cost));
      const desc = clean(ev.product_description || ev.product_excerpt);
      if (desc) descParts.push(desc);
      const DescriptionRaw = descParts.join('\n');
      results.push({
        json: {
          title,
          event_name: title,
          link,
          url: link,
          isoDate,
          start_date: isoDate,
          endDate,
          locationName: venue,
          city,
          sourceCanonical: SOURCE,
          DescriptionRaw,
          _valid: !!(title && isoDate && link),
        }
      });
    }
  }
}
return results;

const SOURCE = 'Unionville';
