  january: 0, february: 1, march: 2, april: 3, may: 4, june: 5,
  july: 6, august: 7, september: 8, october: 9, november: 10, december: 11,
};
// Parse "June 21, 2026" -> "2026-06-21". Manual build avoids new Date() TZ off-by-one.
function parseOneDate(s) {
  const m = (s || '').match(/([A-Za-z]+)\s+(\d{1,2}),\s+(\d{4})/);
  if (!m) return '';
  const mo = MONTHS[m[1].toLowerCase()];
  if (mo === undefined) return '';
  return `${m[3]}-${String(mo + 1).padStart(2, '0')}-${String(m[2]).padStart(2, '0')}`;
}

const html = ($input.first().json.data || '').toString();

// Each card: <div class="news-card" id="news-NNNN" ...> ... </div>. Split on the
// opening boundary; chunk[0] is pre-card noise, the rest are one card each.
const chunks = html.split('<div class="news-card"').slice(1);

