  const hrefMatch = chunk.match(/<a\s+href="([^"]+)"[^>]*class="btn-learn-more"/);
  const link = hrefMatch ? decodeEntities(hrefMatch[1]).trim() : '';

  // No-Z local datetime, matching the VisitVaughan convention (Toronto server TZ).
  const isoDate = startDate ? `${startDate}T00:00:00` : '';

  const descParts = [];
  if (cardTime) descParts.push(`Time: ${cardTime}`);
  if (cardDesc) descParts.push(cardDesc);
  const DescriptionRaw = descParts.join('\n');

  results.push({
    json: {
      title,
      event_name: title,
      link,
      url: link,
      isoDate,
      start_date: isoDate, // window filtered on START (recurring events span months)
      endDate,
      locationName,
      city: CITY,
      sourceCanonical: SOURCE,
      DescriptionRaw,
      _valid: !!(title && startDate && link), // linkless cards drop at Validity Filter
    },
  });
}

return results;

// Facebook manual-intake parser. Each FacebookIntake row = one weekly submission
// (the single tab-separated table the client pastes from the VB_FACEBOOK_INTAKE
// prompt). Emits one item per event in the canonical intermediate shape consumed by
// Merge -> Clean/Filter -> Make UniqueEventID -> Validity Filter -> DateWindow.
// Bad-row policy: skip malformed rows, keep the good ones, log diagnostics.
// uniqueEventID + final _valid are RECOMPUTED downstream by Make UniqueEventID.

const COLUMNS = 6; // Title, StartDate, EndDate, LocationName, City, Link
const ALLOWED_CITIES = ['Vaughan', 'Markham', 'Richmond Hill', 'Toronto'];
const ISO = /^\d{4}-\d{2}-\d{2}$/;
function validISO(s) {
  if (!ISO.test(s)) return false;
  const d = new Date(s + 'T00:00:00Z');
  return !isNaN(d.getTime()) && d.toISOString().slice(0, 10) === s;
}
function matchCity(raw) {
  const v = (raw || '').trim();
  if (!v) return '';
  const h = ALLOWED_CITIES.find((c) => c.toLowerCase() === v.toLowerCase());
  return h || null; // null = present but out-of-set (soft error)
}

const records = ($input.first().json.records) || [];
const out = [];
const errors = [];

for (const rec of records) {
  const blob = (rec.fields && rec.fields.Events) || '';
  // Do NOT trim whole lines: a trailing tab marks an empty final cell (blank Link).
  const lines = blob.split(/\r?\n/).filter((l) => l.trim().length > 0);
  let start = 0;
  if (lines.length && lines[0].split('\t')[0].trim().toLowerCase() === 'title') start = 1;
  for (let i = start; i < lines.length; i++) {
    // Tolerate trailing-tab nondeterminism (study 2026-06-22; mirrors
    // scripts/parseFacebookIntake.js): drop trailing EMPTY overflow cells and pad
    // short rows to 6. A non-empty 7th cell is real corruption and still fails loud.
    let cells = lines[i].split('\t').map((c) => c.trim());
    while (cells.length > COLUMNS && cells[cells.length - 1] === '') cells.pop();
    if (cells.length > COLUMNS) {
      errors.push('rec ' + rec.id + ' line ' + (i + 1) + ': ' + cells.length + ' cols, non-empty overflow - skipped');
      continue;
    }
    while (cells.length < COLUMNS) cells.push('');
    let [title, startDate, endDate, location, city, link] = cells;
    if (!title) {
      errors.push('rec ' + rec.id + ' line ' + (i + 1) + ': no title - skipped');
      continue;
    }
    if (startDate && !validISO(startDate)) {
      errors.push('rec ' + rec.id + ' line ' + (i + 1) + ' "' + title + '": bad StartDate "' + startDate + '" - skipped');
      continue;
    }
    if (endDate && !validISO(endDate)) {
      errors.push('rec ' + rec.id + ' "' + title + '": bad EndDate "' + endDate + '" - cleared');
      endDate = '';
    }
    const cc = matchCity(city);
    if (cc === null) {
      errors.push('rec ' + rec.id + ' "' + title + '": city "' + city + '" not in set - cleared');
      city = '';
    } else {
      city = cc;
    }
    const isoDate = startDate ? startDate + 'T00:00:00' : '';
    out.push({
      json: {
        title,
        event_name: title,
        link,
        url: link,
        isoDate,
        start_date: isoDate,
        endDate,
        locationName: location,
        city,
        sourceCanonical: 'Facebook',
        DescriptionRaw: '',
        _valid: !!(title && startDate && link),
        _intakeRecordId: rec.id,
      },
    });
  }
}
if (errors.length) console.log('[facebook-intake] skipped/cleaned:\n' + errors.join('\n'));
console.log('[facebook-intake] ' + records.length + ' submission(s) -> ' + out.length + ' event item(s)');
return out;

// Facebook manual-intake exception: feed screenshots carry no event URLs, so FB
// events arrive linkless and Make UniqueEventID flags them _valid=false (missing_url).
// Let them through IF they have a date — the editor adds the link at selection time,
// and a pre-publish guard blocks featuring a linkless item. All other sources still
// require a URL. See GH #67 (DOM-extractor spike, deferred).
if ($json.sourceCanonical === 'Facebook' && $json.start_date) {
  return { ...$json, _valid: true, _invalid_reason: '' };
}
return $json;

// Fetch current + next month to cover the 30-day horizon (can cross a month boundary).
// URL month is the lowercase English name (/2026/november). A numeric month (/2026/11) silently
// returns the current month's page, which stamped October programs onto November dates (2026-10-15).
const BASE = 'https://www.vaughanpl.info/events_calendars/calendar';
const MONTHS = ['january', 'february', 'march', 'april', 'may', 'june', 'july', 'august', 'september', 'october', 'november', 'december'];
const now = new Date();
const m1 = new Date(now.getFullYear(), now.getMonth(), 1);
const m2 = new Date(now.getFullYear(), now.getMonth() + 1, 1);
const mk = (d) => ({ json: {
  url: `${BASE}/${d.getFullYear()}/${MONTHS[d.getMonth()]}`,
  year: d.getFullYear(),
  month: d.getMonth() + 1,
} });
return [mk(m1), mk(m2)];

