const DAYS_AHEAD = 30; // mirror DateWindow; skip detail fetches it would drop
const today = new Date();
const startOfToday = new Date(today.getFullYear(), today.getMonth(), today.getDate());
const horizon = new Date(startOfToday); horizon.setDate(horizon.getDate() + DAYS_AHEAD);

function decodeEntities(s) {
  return (s || '').toString()
    .replace(/&#(\d+);/g, (_, n) => String.fromCodePoint(parseInt(n, 10)))
    .replace(/&#x([0-9a-f]+);/gi, (_, n) => String.fromCodePoint(parseInt(n, 16)))
    .replace(/&amp;/g, '&').replace(/&apos;/g, "'").replace(/&quot;/g, '"')
    .replace(/&lt;/g, '<').replace(/&gt;/g, '>').replace(/&nbsp;/g, ' ');
}

const builds = $('VPL Build Months1').all();
const pages = $input.all();
const programs = new Map();

for (let p = 0; p < pages.length; p++) {
  const html = (pages[p].json.data || '').toString();
  const year = builds[p].json.year;
  const month = builds[p].json.month;
  // The page must be the month that was asked for. A wrong month would put every program on the
  // wrong date and look normal, so stop the run instead (2026-10-15).
  const MONTH_NAMES = ['January', 'February', 'March', 'April', 'May', 'June', 'July', 'August', 'September', 'October', 'November', 'December'];
  const header = (html.match(/<th colspan="5" id="c">([^<]*)<\/th>/) || [])[1] || '';
  const wanted = `${MONTH_NAMES[month - 1]} ${year}`;
  if (header.trim() !== wanted) {
    throw new Error(`VPL calendar page for ${wanted} shows "${header.trim() || 'no month header'}"; dates would be wrong, so the run stops.`);
  }

  const cellRe = /<div class="cell-number">(\d+)<\/div>([\s\S]*?)(?=<div class="cell-number">|<\/td>)/g;
  let cm;
  while ((cm = cellRe.exec(html)) !== null) {
    const day = parseInt(cm[1], 10);
    const d = new Date(year, month - 1, day);
    if (d < startOfToday || d > horizon) continue;
    const dateStr = `${year}-${String(month).padStart(2, '0')}-${String(day).padStart(2, '0')}`;

    const aRe = /<a href="\/programs\/view\/(\d+)" title="([^"]*)" class="branch_[^"]*">([\s\S]*?)<\/a>/g;
    let am;
    while ((am = aRe.exec(cm[2])) !== null) {
      const id = am[1];
      const titleAttr = decodeEntities(am[2]).trim();
      const title = decodeEntities(am[3].replace(/<[^>]*>/g, '')).trim();
      const tm = titleAttr.match(/^(\d{1,2}:\d{2}\s*[AP]M)\s+to\s+\d{1,2}:\d{2}\s*[AP]M\s+(.+)$/i);
      const startTime = tm ? tm[1].replace(/\s+/g, ' ') : '';
      const branch = tm ? tm[2].trim() : titleAttr;

      if (!programs.has(id)) {
        programs.set(id, { id, title, detailUrl: `https://www.vaughanpl.info/programs/view/${id}`, occ: [] });
      }
      const prog = programs.get(id);
      // One occurrence per (program, date): "a storytime that day" is enough — same-day
      // multi-branch collapses to the first branch seen (editorial decision 2026-06-24).
      // Keeps VPL key = title|date, identical to every other source (no §59 divergence).
      if (!prog.occ.some((o) => o.date === dateStr)) {
        prog.occ.push({ date: dateStr, branch, startTime });
      }
    }
  }
}

return [...programs.values()].map((p) => ({ json: p }));

