// richmondhill.ca municipal calendar (eSolutionsGroup), Atom feed /default/Rss (issue #78).
// Feed gives title + date + detail URL (more complete than the Month-grid scrape, which
// truncates busy days behind 'View More'). Civic governance events are dropped here at
// ingestion (deterministic); fuzzier B2B/professional-dev is left for R2 classification.
const xmlData = ($input.first().json.data || '').toString();
const CIVIC = /Council|Committee|Advisory|Budget|Task Force|Adjustment|of the Whole|Heritage Richmond Hill|Audit Committee|Roadwatch|Public Meeting|Open House|Endowment|Precinct|Consolidation|Compliance|Master Plan/i;
function decode(s){return (s||'').replace(/&amp;amp;/g,'&').replace(/&amp;/g,'&').replace(/&#39;|&apos;/g,"'").replace(/&quot;/g,'"').replace(/&lt;/g,'<').replace(/&gt;/g,'>').trim();}
const entries=[...xmlData.matchAll(/<entry>([\s\S]*?)<\/entry>/g)].map(m=>m[1]);
const out=[]; const seen=new Set();
for(const e of entries){
  const tm=e.match(/<title type="text">([^<]*?)\s*\((\d+)\/(\d+)\/(\d+)\)<\/title>/);
  const lm=e.match(/href="(https:\/\/calendar\.richmondhill\.ca\/default\/Detail\/[^"]+)"/);
  if(!tm||!lm) continue;                 // need title+date AND a real detail URL (drops empty-Detail entries)
  const title=decode(tm[1]);
  if(!title || CIVIC.test(title)) continue;
  const date=`${tm[4]}-${tm[2].padStart(2,'0')}-${tm[3].padStart(2,'0')}`;
  const detailUrl=lm[1];
  const sm=detailUrl.match(/Detail\/\d{4}-\d{2}-\d{2}-(\d{4})-/);
  const time=sm?`${sm[1].slice(0,2)}:${sm[1].slice(2)}`:'00:00';
  const isoDate=`${date}T${time}:00`;
  const key=`${title}|${date}`;
  if(seen.has(key)) continue; seen.add(key);
  out.push({json:{title,date,isoDate,detailUrl}});
}
return out;

