// Pinot's Palette Woodbridge - single-page SSR Doc scrape (Tier 4).
// All 73 events render on /woodbridge with title+date inline; no detail hop.
// Cards double-render (image-card + book-now-card); dedupe by event id, first wins.
// Single venue -> City=Vaughan by definition. UniqueEventID built downstream by Make UniqueEventID.
const SOURCE='PinotsPalette', CITY='Vaughan', LOCATION="Pinot's Palette - Vaughan-Woodbridge";
const MONTHS={Jan:0,Feb:1,Mar:2,Apr:3,May:4,Jun:5,Jul:6,Aug:7,Sep:8,Oct:9,Nov:10,Dec:11};
function decodeEntities(s){return (s||'').toString().replace(/&#(\d+);/g,(_,n)=>String.fromCodePoint(parseInt(n,10))).replace(/&#x([0-9a-f]+);/gi,(_,n)=>String.fromCodePoint(parseInt(n,16))).replace(/&amp;/g,'&').replace(/&apos;/g,"'").replace(/&quot;/g,'"').replace(/&lt;/g,'<').replace(/&gt;/g,'>').replace(/&nbsp;/g,' ');}
function parseDate(t){const m=(t||'').match(/\w{3}\s+(\w{3})\s+(\d{1,2}),\s+(\d{4})/);if(!m)return '';const mon=MONTHS[m[1]];if(mon===undefined)return '';const dt=new Date(Date.UTC(+m[3],mon,+m[2],12,0,0));if(isNaN(dt.getTime()))return '';return dt.toISOString();}
const html=($input.first().json.data||'').toString();
const blocks=html.split('<figure');
const byId=new Map();
for(const b of blocks){
  const idm=b.match(/\/woodbridge\/event\/(\d+)/); if(!idm) continue;
  const id=idm[1];
  const tm=b.match(/<h4 class="time">([^<]+)<\/h4>/);
  const hm=b.match(/<h3>([^<]+)<\/h3>/);
  if(!tm||!hm) continue;
  const title=decodeEntities(hm[1]).trim();
  const isoDate=parseDate(tm[1]);
  if(!title||!isoDate) continue;
  if(byId.has(id)) continue;
  const url='https://www.pinotspalette.com/woodbridge/event/'+id;
  // #84 - cost signal, clean consistent "$NN per guest" format confirmed live.
  const pm=b.match(/<h4 class="price">([^<]+)<\/h4>/);
  const costRaw=pm?pm[1].trim():'';
  byId.set(id,{json:{title,event_name:title,link:url,url,isoDate,start_date:isoDate,endDate:'',locationName:LOCATION,city:CITY,sourceCanonical:SOURCE,DescriptionRaw:'',costRaw,_valid:!!(title&&isoDate&&url)}});
}
return [...byId.values()];

