// The Chef Upstairs (#80) - BookThatApp availability feed (Tier 1 JSON).
// schedule.json?location=13173 returns the Vaughan studio's forward-dated class occurrences.
// products.json has NO date; the date lives only in this booking feed (start[] array / select= ISO).
// Each occurrence (a class on a specific date) = one event; recurring classes appear once per date.
// Single Vaughan venue -> City=Vaughan. UniqueEventID built downstream by Make UniqueEventID.
// DescriptionRaw is enriched from products.json body_html (joined on handle) - the schedule feed has
// no description, and R6 scoring / R7 classification consume DescriptionRaw. Enrichment is non-critical:
// if the products fetch fails or a handle is missing, DescriptionRaw falls back to '' and events still flow.
const SOURCE='ChefUpstairs', CITY='Vaughan', LOCATION='The Chef Upstairs - Vaughan', LOC_ID=13173;
// Multi-day programs (camps / multi-week sessions / series) are a different event SHAPE than the
// single-night classes the weekly newsletter runs. Client confirmed (2026-07-02 mtg) they want these
// IN the pool too (will rarely pick them). One entry per program in the feed (start=first day, full
// range in the title) -> no per-day spam; UniqueEventID=title|date keeps them distinct.
const DROP_MULTIDAY=false;
const MULTIDAY=/\bcamp\b|\b\d+\s*week\b|\bweek\s*\d|\b(fall|spring|winter|summer)\s+session\b|\bseries\b/i;
function decodeEntities(s){return (s||'').toString().replace(/&#(\d+);/g,(_,n)=>String.fromCodePoint(parseInt(n,10))).replace(/&#x([0-9a-f]+);/gi,(_,n)=>String.fromCodePoint(parseInt(n,16))).replace(/&amp;/g,'&').replace(/&apos;/g,"'").replace(/&quot;/g,'"').replace(/&lt;/g,'<').replace(/&gt;/g,'>').replace(/&nbsp;/g,' ');}
function htmlToText(h){return decodeEntities((h||'').toString().replace(/<\s*(br|\/p|\/li|\/h[1-6])\s*>/gi,' ').replace(/<[^>]+>/g,' ')).replace(/\s+/g,' ').trim().slice(0,1000);}
function cleanTitle(t){let s=decodeEntities(t).replace(/\s+/g,' ').trim();s=s.replace(/^Vaughan\s*-\s*/i,'');s=s.replace(/^(Adult|Kids|Teen|Parent and Child|Single)[^-:]*Cooking (Class|Classes|Camp)\s*[-:]\s*/i,'');s=s.replace(/^Food Lover[’'s]+[^-:]*Cooking Class\s*[-:]\s*/i,'');return s.trim();}
// --- enrich: fetch products.json (2 pages, 250 cap) and map handle -> plaintext description ---
const byHandle={};
try{
  for(const page of [1,2]){
    const res=await this.helpers.httpRequest({url:'https://thechefupstairs.com/products.json?limit=250&page='+page,json:true,headers:{'User-Agent':'Mozilla/5.0','Accept':'application/json'}});
    const ps=(res&&res.products)||[];
    for(const p of ps){ if(!(p.handle in byHandle)) byHandle[p.handle]=htmlToText(p.body_html); }
  }
}catch(e){ /* non-critical: leave byHandle partial/empty, descriptions fall back to '' */ }
const response=$input.first().json;
const sched=(response.schedule)||[];
const out=[];
for(const ev of sched){
  const locId=ev.locations&&ev.locations[0]&&ev.locations[0].id;
  if(locId!==LOC_ID) continue;                 // Vaughan studio only (guard vs the fetch location filter)
  if(ev.bookedOut===true) continue;            // drop sold-out (no valid CTA)
  const rawTitle=(ev.title||'').toString();
  if(DROP_MULTIDAY && MULTIDAY.test(rawTitle)) continue;  // drop camps/sessions (#80 toggle)
  const a=ev.start; if(!Array.isArray(a)||a.length<5) continue;
  const dt=new Date(Date.UTC(a[0],a[1]-1,a[2],a[3],a[4],0));  // start[] month is 1-indexed
  if(isNaN(dt.getTime())) continue;
  const isoDate=dt.toISOString();
  const isMulti=MULTIDAY.test(rawTitle);
  // cleanTitle strips the "Kids/Teen ... Cooking Camp -" boilerplate, which for a camp IS the subject
  // (would leave only "Week 5 - July 20-25"). Multi-day: keep the descriptor, strip only the venue prefix.
  const title=isMulti
    ? decodeEntities(rawTitle).replace(/\s+/g,' ').replace(/^Vaughan\s*-\s*/i,'').trim()
    : cleanTitle(rawTitle);
  const path=(ev.url||'').replace(/^https?:\/\/[^/]+/,'');
  const url='https://thechefupstairs.com'+path;
  if(!title||!isoDate||!url) continue;
  const DescriptionRaw=byHandle[ev.handle]||'';
  out.push({json:{title,event_name:title,link:url,url,isoDate,start_date:isoDate,endDate:'',locationName:LOCATION,city:CITY,sourceCanonical:SOURCE,DescriptionRaw,_valid:!!(title&&isoDate&&url)}});
}
return out;

// BiblioCommons blocks Node's default TLS fingerprint with a 403.
// Headers/User-Agent do not help - the block happens during the TLS
// handshake, before any header is sent. Presenting Chrome's cipher
// ordering gets a 200. Verified 2026-08-27.
const https = require('https');

const CIPHERS = [
  'TLS_AES_128_GCM_SHA256',
  'TLS_AES_256_GCM_SHA384',
  'TLS_CHACHA20_POLY1305_SHA256',
  'ECDHE-ECDSA-AES128-GCM-SHA256',
  'ECDHE-RSA-AES128-GCM-SHA256',
  'ECDHE-ECDSA-AES256-GCM-SHA384',
  'ECDHE-RSA-AES256-GCM-SHA384',
  'ECDHE-ECDSA-CHACHA20-POLY1305',
  'ECDHE-RSA-CHACHA20-POLY1305',
  'ECDHE-RSA-AES128-SHA',
  'ECDHE-RSA-AES256-SHA',
  'AES128-GCM-SHA256',
  'AES256-GCM-SHA384',
  'AES128-SHA',
  'AES256-SHA'
].join(':');

const URL = 'https://markham.bibliocommons.com/events/rss/all';

const xml = await new Promise((resolve, reject) => {
  const req = https.get(
    URL,
    {
      ciphers: CIPHERS,
      minVersion: 'TLSv1.2',
      headers: {
        'User-Agent':
          'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/126.0.0.0 Safari/537.36',
        Accept: 'application/rss+xml, application/xml;q=0.9, */*;q=0.8',
        'Accept-Language': 'en-CA,en;q=0.9'
      }
    },
    (res) => {
      if (res.statusCode !== 200) {
        res.resume();
        reject(new Error('BiblioCommons fetch failed: HTTP ' + res.statusCode));
        return;
      }
      let body = '';
      res.setEncoding('utf8');
      res.on('data', (c) => (body += c));
      res.on('end', () => resolve(body));
    }
  );
  req.on('error', reject);
  req.setTimeout(30000, () => req.destroy(new Error('BiblioCommons fetch timed out')));
});

// Normalize1 reads $input.first().json.data - keep that shape.
return [{ json: { data: xml } }];

