// Eventbrite search (replaces city-browse, 2026-10-15). city-browse returns ~10 themed buckets of
// ~8 events with no paging or dates (~80 events in all); this is the search the website uses, over
// a box around Vaughan, Markham and Richmond Hill, every page, for the next DAYS_AHEAD days.
// The box also catches Toronto, Brampton and Aurora: Normalize's CITY_MAP gate still decides.
// Uses the csrftoken from Get EB Token, as city-browse did.
const https = require('https');

const DAYS_AHEAD = 30;
const BBOX = '-79.75,43.74,-79.15,44.00'; // west,south,east,north; padded: the southernmost in-area venue is at 43.769
const PAGE_SIZE = 50;     // the API clamps larger values to 50
const SERVE_CAP_PAGES = 19; // the API stops serving after ~19 pages; reaching it means events were cut off

const setCookie = $('Get EB Token').first().json.headers['set-cookie'] || [];
const token = (setCookie.join(';').match(/csrftoken=([^;]+)/) || [])[1];
if (!token) throw new Error('Eventbrite: no csrftoken from Get EB Token');
const cookie = setCookie.map((c) => c.split(';')[0]).join('; ');

const ymd = (d) => d.toLocaleDateString('en-CA', { timeZone: 'America/Toronto' });
// Searched a week at a time: one 30-day search returned 104 in-area events for Oct 23 - Nov 1
// where a 10-day search of the same box returned 178. Long ranges come back thinned, with no sign.
const CHUNK_DAYS = 7;
const start = new Date();
const chunks = [];
for (let d = 0; d < DAYS_AHEAD; d += CHUNK_DAYS) {
  const a = new Date(start.getTime() + d * 86400000);
  const b = new Date(start.getTime() + Math.min(d + CHUNK_DAYS - 1, DAYS_AHEAD) * 86400000);
  chunks.push({ from: ymd(a), to: ymd(b) });
}

function post(range, page) {
  const body = JSON.stringify({
    event_search: { bbox: BBOX, date_range: range, dates: 'current_future',
      dedup: false, page, page_size: PAGE_SIZE },
    'expand.destination_event': ['primary_venue', 'ticket_availability', 'primary_organizer', 'image',
      'event_sales_status', 'saves', 'series'],
    browse_surface: 'search',
  });
  return new Promise((resolve, reject) => {
    const req = https.request('https://www.eventbrite.com/api/v3/destination/search/', {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        'Content-Length': Buffer.byteLength(body),
        'X-CSRFToken': token,
        Cookie: cookie,
        Referer: 'https://www.eventbrite.com/d/canada--york/events/',
        'User-Agent': 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/124.0.0.0 Safari/537.36',
      },
    }, (res) => {
      let data = '';
      res.setEncoding('utf8');
      res.on('data', (c) => (data += c));
      res.on('end', () => {
        if (res.statusCode !== 200) return reject(new Error(`Eventbrite search page ${page}: HTTP ${res.statusCode}`));
        try { resolve(JSON.parse(data)); } catch (e) { reject(new Error(`Eventbrite search page ${page}: not JSON`)); }
      });
    });
    req.on('error', reject);
    req.setTimeout(30000, () => req.destroy(new Error(`Eventbrite search page ${page} timed out`)));
    req.end(body);
  });
}

// A page takes about 4 s to come back, so pages are fetched four at a time: one at a time, the
// ~29 pages took about 2.5 minutes (2026-10-15).
const CONCURRENCY = 4;
async function inBatches(tasks) {
  const out = [];
  let next = 0;
  const worker = async () => { while (next < tasks.length) { const k = next++; out[k] = await tasks[k](); } };
  await Promise.all(Array.from({ length: Math.min(CONCURRENCY, tasks.length) }, worker));
  return out;
}

const byId = new Map();
const add = (r) => { for (const e of (r.events && r.events.results) || []) if (e && e.id && !byId.has(e.id)) byId.set(e.id, e); };
// Page 1 of every week first: it says how many pages that week has.
const firsts = await inBatches(chunks.map((range) => () => post(range, 1)));
const pagesPerChunk = firsts.map((r) => (r.events && r.events.pagination && r.events.pagination.page_count) || 1);
pagesPerChunk.forEach((count, i) => {
  if (count >= SERVE_CAP_PAGES) {
    throw new Error(`Eventbrite search for ${chunks[i].from}..${chunks[i].to} hit the ${SERVE_CAP_PAGES}-page serve cap; events would be missing. Shorten CHUNK_DAYS.`);
  }
});
firsts.forEach(add);
const rest = [];
chunks.forEach((range, i) => { for (let p = 2; p <= pagesPerChunk[i]; p++) rest.push(() => post(range, p)); });
(await inBatches(rest)).forEach(add);
if (byId.size === 0) throw new Error('Eventbrite search returned no events; the request has probably changed.');

// Normalize reads events.results.
return [{ json: { events: { results: [...byId.values()] }, pages: pagesPerChunk } }];

// AllEvents' list API refuses requests without an X-Client-State header since about 2026-09-12: it
// answers HTTP 200 {"error":1,"message":"invalid_request"} with no events. The token sits in every
// city page as window.__cst, lasts 10 minutes and is tied to the caller's IP, so it is fetched fresh
// on every run, from this machine, right before the three list requests (2026-10-15).
const https = require('https');
const UA = 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/124.0.0.0 Safari/537.36';

const html = await new Promise((resolve, reject) => {
  const req = https.get('https://allevents.in/vaughan-on/all', { headers: { 'User-Agent': UA, Accept: 'text/html' } }, (res) => {
    if (res.statusCode !== 200) { res.resume(); return reject(new Error(`AllEvents token page: HTTP ${res.statusCode}`)); }
    let body = '';
    res.setEncoding('utf8');
    res.on('data', (c) => (body += c));
    res.on('end', () => resolve(body));
  });
  req.on('error', reject);
  req.setTimeout(30000, () => req.destroy(new Error('AllEvents token page timed out')));
});

const m = html.match(/window\.__cst\s*=\s*"([^"]+)"/);
if (!m) throw new Error('AllEvents: no X-Client-State token (window.__cst) on /vaughan-on/all; the site has changed again.');
return [{ json: { cst: m[1] } }];
